def _handle_dict(target, spec, scope):
    if not isinstance(target, dict):
        raise TypeMatchError(type(target), dict)
    if type(spec) is not type(target):
        raise TypeMatchError(type(target), type(spec))

    result = {}
    unmatched_target_keys = list(target.keys())
    spec_keys_sorted = sorted(spec.keys(), key=_precedence)

    for spec_key in spec_keys_sorted:
        val_spec = spec[spec_key]
        actual_key = spec_key.key if type(spec_key) in (Optional, Required) else spec_key
        is_required = type(spec_key) is Required or (type(spec_key) is not Optional and _precedence(spec_key) == 0)

        matched_any = False
        for target_key in list(unmatched_target_keys):
            try:
                scope[glom](target_key, actual_key, scope)
            except GlomError:
                continue
            matched_val = scope[glom](target[target_key], val_spec, scope)
            result[target_key] = matched_val
            unmatched_target_keys.remove(target_key)
            matched_any = True
            if _precedence(actual_key) == 0:
                break

        if not matched_any:
            if is_required:
                raise MatchError("target missing expected keys {0}", spec_key)
            elif type(spec_key) is Optional and spec_key.default is not _MISSING:
                result[spec_key.key] = spec_key.default

    if unmatched_target_keys:
        raise MatchError("target has extra keys: {0!r}", unmatched_target_keys)

    return result
